package cli

import (
 "context"
 "os"
 "path/filepath"
 "strings"
 "testing"
 "time"

 "github.com/ashtom/entire-brain/internal/entityindex"
 "github.com/spf13/cobra"
)

type upgradeGraphRunner struct{ graph string }
func (r *upgradeGraphRunner) Run(ctx context.Context,dir,name string,args ...string)([]byte,[]byte,error){
 if name=="entire" && len(args)>0 && args[0]=="graph" {return (ExecRunner{}).Run(ctx,dir,r.graph,args[1:]...)}
 return (ExecRunner{}).Run(ctx,dir,name,args...)
}

// Run against actual pre/post-upgrade Graph builds. The source tree and source
// commit stay unchanged during the provider switch; mocks cannot establish this.
func TestGraphIdentityUpgradeLive(t *testing.T){
 before,after:=os.Getenv("BRAIN_TEST_GRAPH_BEFORE"),os.Getenv("BRAIN_TEST_GRAPH_AFTER")
 if before==""||after==""{t.Skip("set BRAIN_TEST_GRAPH_BEFORE and BRAIN_TEST_GRAPH_AFTER to Graph binaries")}
 t.Setenv("GIT_CONFIG_GLOBAL",os.DevNull);t.Setenv("GIT_CONFIG_SYSTEM",os.DevNull)
 repo:=t.TempDir();ctx:=context.Background();r:=&upgradeGraphRunner{before}
 git:=func(args ...string)string{t.Helper();out,stderr,err:=r.Run(ctx,repo,"git",args...);if err!=nil{t.Fatalf("git %v: %v %s",args,err,stderr)};return strings.TrimSpace(string(out))}
 git("init","-b","main");git("config","user.name","Upgrade test");git("config","user.email","upgrade@example.invalid");git("remote","add","origin","https://github.com/example/repo.git")
 write:=func(value string){t.Helper();for _,ext:=range []string{"js","ts"}{src:="class A {\n  m() {\n    function helper() { return "+value+"; }\n    return helper();\n  }\n}\n";if err:=os.WriteFile(filepath.Join(repo,"a."+ext),[]byte(src),0600);err!=nil{t.Fatal(err)}}}
 write("1");git("add",".");git("commit","-m","first\n\nEntire-Checkpoint: abc123abc123")
 first:=git("rev-parse","HEAD");write("2");git("commit","-am","second\n\nEntire-Checkpoint: def456def456");head:=git("rev-parse","HEAD")
 env:=semanticTestEnv(t,repo);opts:=Options{Env:env,Runner:r,Now:time.Now,Version:"test"}
