	for attempt := 0; attempt < maxRefCASRetries; attempt++ {
		st, headRefObj, err := s.state()
		if err != nil {
			return "", err
		}
		next, err := mutate(st)
		if errors.Is(err, ErrNoUpdate) {
			if headRefObj == nil {
				return "", nil
			}
			return headRefObj.Hash().String(), nil
