		if err != nil {
			return "", fmt.Errorf("factgitmeta: serialize: %w", err)
		}
		info := gitmeta.CommitInfo{
			AuthorName:  "entire-brain",
			AuthorEmail: "brain@entire.local",
			When:        s.now().UTC(),
			Message:     gitmeta.SerializeMessage(records),
